# ======================= Semaine du 23 au 29/11 (production du dimanche 22/11) =======================
# Chaque VOICE = TEXTS + 2 à 4 balises d'expression + nombres en toutes lettres + « [pause] Allez, ciao. » (phrase sacrifiée)
def _voice(k, tags, nums=()):
    v = TEXTS[k]
    for a, b in list(tags) + list(nums):
        assert a in v, (k, a)
        v = v.replace(a, b, 1) if a in dict(tags) else v.replace(a, b)
    return v + " [pause] Allez, ciao."

